import {createFilter, listFilters, getFilter, updateFilter, deleteFilter} from './filters.js';
import {searchAccess, searchIssues} from './search.js';

export function registerFilterRoutes(ctx) {
  const {app, requireAuth} = ctx;
  app.get('/api/v1/filters', requireAuth, (req, res) => res.json(listFilters(ctx, req)));
  app.post('/api/v1/filters', requireAuth, (req, res) => res.status(201).json({filter: createFilter(ctx, req, req.body)}));
  app.get('/api/v1/filters/options', requireAuth, (req, res) => {
    const access = searchAccess(ctx, req);
    const allowed = new Set(access.projectIds);
    const projects = ctx.db.prepare('SELECT id,key,name FROM projects WHERE org_id=? ORDER BY key,id').all(access.orgId).filter(project => allowed.has(project.id));
    const teams = ctx.db.prepare('SELECT t.id,t.name FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE t.org_id=? AND tm.user_id=? ORDER BY t.name,t.id').all(access.orgId, req.user.id);
    res.json({projects, teams});
  });
  app.get('/api/v1/filters/:filterId', requireAuth, (req, res) => res.json({filter: getFilter(ctx, req, req.params.filterId)}));
  app.patch('/api/v1/filters/:filterId', requireAuth, (req, res) => res.json({filter: updateFilter(ctx, req, req.params.filterId, req.body)}));
  app.delete('/api/v1/filters/:filterId', requireAuth, (req, res) => {
    deleteFilter(ctx, req, req.params.filterId);
    res.json({ok: true});
  });
  app.get('/api/v1/filters/:filterId/search', requireAuth, (req, res) => {
    const filter = getFilter(ctx, req, req.params.filterId);
    res.json({...searchIssues(ctx, req, {...req.query, orgId: filter.orgId, q: filter.query}), filter});
  });
}

import {useState} from 'preact/hooks';
import {Field, Button, Notice} from '../../components/ui.jsx';
import {filterDraft, filterPayload} from './search-state.js';
import {savedFilterInput} from '../../../../../shared/src/index.js';

export function FilterForm({api, filter, orgId, teams = [], onSaved, onCancel}) {
  const [draft, setDraft] = useState(() => filterDraft(filter, orgId));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const update = (field, value) => setDraft(previous => ({...previous, [field]: value}));
  const details = error?.details ?? {};
  async function save(event) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const payload = filterPayload(draft, filter?.revision);
      const {expectedRevision, ...validated} = payload;
      savedFilterInput(validated);
      if (draft.visibility === 'team' && !draft.teamId) throw new Error('Choose a team to share this filter');
      const result = filter?.id ? await api.patch('/filters/' + filter.id, payload) : await api.post('/filters', payload);
      onSaved(result.filter);
    } catch (failure) {setError(failure);}
    finally {setBusy(false);}
  }
  return <form className="filter-form" onSubmit={save}>
    <h2>{filter?.id ? 'Edit saved filter' : 'Save this search'}</h2>
    <Notice error={error}/>
    <Field label="Name" error={details.name} value={draft.name} required maxLength={100} onInput={event => update('name', event.currentTarget.value)}/>
    <Field label="Description" error={details.description}>
      <textarea value={draft.description} maxLength={1000} onInput={event => update('description', event.currentTarget.value)}/>
    </Field>
    <Field label="Query" error={details.query}>
      <textarea value={draft.query} maxLength={4000} onInput={event => update('query', event.currentTarget.value)} aria-label="Saved filter query"/>
    </Field>
    <Field label="Visibility" error={details.visibility}>
      <select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="personal">Personal · only you</option>
        <option value="team">Shared with a team</option>
      </select>
    </Field>
    {draft.visibility === 'team' && <Field label="Team" error={details.teamId}>
      <select required value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">Choose one of your teams</option>
        {teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select>
      {!teams.length && <p>Join a team in this organization before sharing a filter.</p>}
    </Field>}
    <p>Every run uses the current viewer’s project access. Only the creator can edit or delete a filter.</p>
    <div className="actions"><Button busy={busy} type="submit">Save filter</Button><Button type="button" disabled={busy} onClick={onCancel}>Cancel</Button></div>
  </form>;
}

import {useEffect, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {searchLocation} from './search-state.js';

export function FiltersPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [visibility, setVisibility] = useState('all');
  const [owned, setOwned] = useState(false);
  const [teamId, setTeamId] = useState('');
  const [cursors, setCursors] = useState(['']);
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: []}, [orgId]);
  const listing = useLoad(() => {
    if (!orgId) return {items: [], total: 0};
    return api.get('/filters?' + new URLSearchParams({orgId, visibility, owned: String(owned), teamId, limit: '25', cursor: cursors.at(-1)}));
  }, [orgId, visibility, owned, teamId, cursors.at(-1)]);
  useEffect(() => {if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);}, [organizations.data]);
  function changeOrg(value) {
    setOrgId(value);
    setTeamId('');
    setCursors(['']);
    setEditing(null);
    setMessage('');
  }
  async function remove(filter) {
    setError(null);
    setBusy(true);
    try {
      await api.delete('/filters/' + filter.id);
      setMessage('Deleted “' + filter.name + '”.');
      setCursors(['']);
      listing.reload();
    } catch (failure) {setError(failure);}
    finally {setBusy(false);}
  }
  async function edit(filter) {
    setError(null);
    try {setEditing((await api.get('/filters/' + filter.id)).filter);}
    catch (failure) {setError(failure);}
  }
  return <Page title="Saved filters" actions={<a href={routeLink('/search', {orgId})}>Search issues</a>}>
    <Notice error={error ?? organizations.error ?? listing.error ?? options.error}/><Notice>{message}</Notice>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Join an organization before saving a filter.</Empty> : <>
      <div className="search-controls">
        <Field label="Organization"><select value={orgId} onChange={event => changeOrg(event.currentTarget.value)}>
          <option value="">Choose an organization</option>{organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
        </select></Field>
        <Field label="Visibility"><select value={visibility} onChange={event => {setVisibility(event.currentTarget.value); setCursors(['']);}}>
          <option value="all">Personal and shared</option><option value="personal">Personal</option><option value="team">Team shared</option>
        </select></Field>
        <Field label="Team"><select value={teamId} onChange={event => {setTeamId(event.currentTarget.value); setCursors(['']);}}>
          <option value="">All my teams</option>{options.data?.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
        </select></Field>
        <label><input type="checkbox" checked={owned} onChange={event => {setOwned(event.currentTarget.checked); setCursors(['']);}}/>Created by me</label>
      </div>
      <Button disabled={!orgId || busy} onClick={() => setEditing({})}>Create saved filter</Button>
      {editing && <FilterForm key={editing.id ?? 'new'} api={api} orgId={orgId} filter={editing} teams={options.data?.teams}
        onCancel={() => setEditing(null)} onSaved={filter => {setEditing(null); setMessage('Saved “' + filter.name + '”.'); setCursors(['']); listing.reload();}}/>}
      {listing.loading ? <Loading/> : !listing.data?.items.length ? <Empty>No saved filters in this view. Create one or ask a teammate to share one.</Empty> : <>
        <p>{listing.data.total} accessible filters</p>
        <ul className="saved-filters">{listing.data.items.map(filter => <li key={filter.id}>
          <article><h2><a href={'#' + searchLocation(filter.orgId, filter.query)}>{filter.name}</a></h2>
            {filter.description && <p>{filter.description}</p>}
            <pre>{filter.query || 'All accessible issues'}</pre>
            <p>{filter.visibility === 'personal' ? 'Personal' : 'Team: ' + (options.data?.teams.find(team => team.id === filter.teamId)?.name ?? 'Shared team')} · revision {filter.revision}</p>
            <div className="actions"><Button onClick={() => navigate(searchLocation(filter.orgId, filter.query))}>Run filter</Button>
              {filter.canEdit && <><Button disabled={busy} onClick={() => edit(filter)}>Edit</Button>
                <ConfirmButton disabled={busy} message={'Delete saved filter “' + filter.name + '”?'} onConfirm={() => remove(filter)}>Delete</ConfirmButton></>}
            </div>
          </article>
        </li>)}</ul>
        <div className="actions"><Button disabled={busy || cursors.length < 2} onClick={() => setCursors(previous => previous.slice(0, -1))}>Previous</Button>
          <span>Page {cursors.length}</span><Button disabled={busy || !listing.data.nextCursor} onClick={() => setCursors(previous => [...previous, listing.data.nextCursor])}>Next</Button></div>
      </>}
    </>}
  </Page>;
}

import {SearchPage} from './search.jsx';
import {FiltersPage} from './filters.jsx';
import '../../styles/insight-search.css';

export const searchRoutes = [
  {path: '/search', component: SearchPage},
  {path: '/filters', component: FiltersPage}
];
export const searchNavigation = [
  {path: '/search', label: 'Search'},
  {path: '/filters', label: 'Saved filters'}
];

import {validatedQuery, quoteQueryValue} from '../../../../../shared/src/index.js';

export function searchLocation(orgId, query, projectId = '') {
  const params = new URLSearchParams({orgId, q: query});
  if (projectId) params.set('projectId', projectId);
  return '/search?' + params;
}

export function searchRequest({orgId, query = '', projectId = '', cursor = '', limit = 25}) {
  if (!orgId) throw new Error('Choose an organization before searching');
  const parsed = validatedQuery(query);
  const params = new URLSearchParams({orgId, q: parsed.query, limit: String(limit)});
  if (projectId) params.set('projectId', projectId);
  if (cursor) params.set('cursor', cursor);
  return '/search?' + params;
}

export function appendQueryFilter(query, field, value) {
  const filter = field + ':' + quoteQueryValue(value);
  const base = query.trim();
  return base ? '(' + base + ') AND ' + filter : filter;
}

export function filterDraft(filter = {}, orgId = '') {
  return {orgId: filter.orgId ?? orgId, name: filter.name ?? '', query: filter.query ?? '',
    description: filter.description ?? '', visibility: filter.visibility ?? 'personal', teamId: filter.teamId ?? ''};
}

export function filterPayload(draft, revision) {
  const payload = {...draft, teamId: draft.visibility === 'team' ? draft.teamId || null : null};
  if (revision != null) payload.expectedRevision = revision;
  return payload;
}

export function nextSearchPage(history, cursor) {
  return [...history, cursor ?? ''];
}

export function previousSearchPage(history) {
  return history.length > 1 ? history.slice(0, -1) : [''];
}

export function errorPosition(error) {
  if (!Number.isInteger(error?.details?.offset)) return null;
  return {offset: error.details.offset, end: error.details.end,
    description: 'Line ' + error.details.line + ', column ' + error.details.column};
}

import {useEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {searchRequest, searchLocation, appendQueryFilter, nextSearchPage, previousSearchPage, errorPosition} from './search-state.js';

export function Highlight({segments = []}) {
  return <>{segments.map((part, index) => part.match ? <mark key={index}>{part.text}</mark> : <span key={index}>{part.text}</span>)}</>;
}

export function SearchHelp() {
  return <details><summary>Query language and examples</summary>
    <p>Use words for token prefixes, or quotes for an exact phrase. Adjacent terms mean AND. NOT binds before AND, then OR. Parentheses override precedence.</p>
    <ul>
      <li><code>status:active AND assignee:@me</code> · my active issues</li>
      <li><code>project:APP AND (label:bug OR priority&gt;=3)</code> · urgent work</li>
      <li><code>created&gt;2026-01-01 AND updated&lt;2027-01-01</code> · UTC date window</li>
      <li><code>"search index" AND NOT status:done</code> · exact phrase excluding completed work</li>
    </ul>
    <p>Filter values match exact IDs or names; quote names with spaces. Priority ranges from 0 to 4. Dates use YYYY-MM-DD; quote full UTC ISO timestamps.</p>
  </details>;
}

export function SearchPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [input, setInput] = useState(query.q ?? '');
  const [projectId, setProjectId] = useState(query.projectId ?? '');
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const [suggestionError, setSuggestionError] = useState(null);
  const [history, setHistory] = useState(['']);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState('');
  const inputRef = useRef(null);
  const requestVersion = useRef(0);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: [], projects: []}, [orgId]);
  useEffect(() => {
    if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);
  }, [organizations.data]);
  useEffect(() => {
    setOrgId(query.orgId ?? '');
    setInput(query.q ?? '');
    setProjectId(query.projectId ?? '');
    setResults(null);
    setHistory(['']);
    requestVersion.current++;
  }, [query.orgId, query.q, query.projectId]);
  useEffect(() => {
    if (!orgId) {setSuggestions([]); return;}
    let active = true;
    const timer = setTimeout(() => {
      const params = new URLSearchParams({orgId, q: input, caret: String(inputRef.current?.selectionStart ?? input.length)});
      if (projectId) params.set('projectId', projectId);
      api.get('/search/suggestions?' + params).then(data => {
        if (active) {setSuggestions(data.items); setSuggestionError(null);}
      }, failure => {if (active) {setSuggestions([]); setSuggestionError(failure);}});
    }, 200);
    return () => {active = false; clearTimeout(timer);};
  }, [input, orgId, projectId]);
  async function run(event, nextHistory = ['']) {
    event?.preventDefault();
    const version = ++requestVersion.current;
    setBusy(true);
    setError(null);
    setSaved('');
    try {
      const path = searchRequest({orgId, query: input, projectId, cursor: nextHistory.at(-1)});
      const data = await api.get(path);
      if (version !== requestVersion.current) return;
      setResults(data);
      setHistory(nextHistory);
    } catch (failure) {if (version === requestVersion.current) {setError(failure); setResults(null);}}
    finally {if (version === requestVersion.current) setBusy(false);}
  }
  function chooseSuggestion(suggestion) {
    setInput(suggestion.query);
    inputRef.current?.focus();
  }
  const position = errorPosition(error);
  return <Page title="Search issues" actions={<a href={routeLink('/filters', {orgId})}>Saved filters</a>}>
    <Notice error={organizations.error ?? options.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Create or join an organization to search its work.</Empty> : <>
      <form onSubmit={run}>
        <div className="search-controls">
          <Field label="Organization"><select value={orgId} onChange={event => {setOrgId(event.currentTarget.value); setProjectId(''); setResults(null);}}>
            <option value="">Choose an organization</option>
            {organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
          </select></Field>
          <Field label="Project"><select value={projectId} onChange={event => {setProjectId(event.currentTarget.value); setResults(null);}}>
            <option value="">All accessible projects</option>
            {(options.data?.projects ?? []).map(project => <option key={project.id} value={project.id}>{project.key} · {project.name}</option>)}
          </select></Field>
        </div>
        <Field label="Query" error={error?.details?.query}>
          <input ref={inputRef} data-testid="search-query" aria-label="Search query" value={input} maxLength={4000} onInput={event => setInput(event.currentTarget.value)} spellCheck={false}/>
        </Field>
        {position && <p role="alert">{position.description} <button type="button" onClick={() => {inputRef.current.focus(); inputRef.current.setSelectionRange(position.offset, position.end);}}>Select query error</button></p>}
        <div className="actions"><Button busy={busy} disabled={!orgId} type="submit">Search</Button>
          <Button type="button" disabled={!orgId || busy} onClick={() => setSaving(true)}>Save search</Button>
          <Button type="button" onClick={() => {setInput(''); setResults(null); setHistory(['']);}}>Clear</Button></div>
      </form>
      <Notice error={error}/><Notice>{saved}</Notice>
      <SearchHelp/>
      <aside className="query-suggestions" aria-label="Query suggestions">
        <h2>Suggestions</h2><Notice error={suggestionError}/>
        {!suggestions.length ? <p>Type a filter field such as status: or label: for values.</p> : <ul>{suggestions.map(item => <li key={item.replacement}>
          <button type="button" onClick={() => chooseSuggestion(item)}>{item.label}</button> <small>{item.description}</small>
        </li>)}</ul>}
      </aside>
      {saving && <FilterForm key={orgId + input} api={api} orgId={orgId} filter={{query: input}} teams={options.data?.teams}
        onCancel={() => setSaving(false)} onSaved={filter => {setSaving(false); setSaved('Saved “' + filter.name + '”.');}}/>}
      {busy && <Loading/>}
      {results && <section aria-label="Search results">
        <h2>{results.total} {results.total === 1 ? 'issue' : 'issues'} found</h2>
        <div className="search-facets">{Object.entries(results.facets ?? {}).map(([field, values]) => <details key={field}>
          <summary>{field}</summary>{values.map(item => <Button key={String(item.value)} onClick={() => {setInput(appendQueryFilter(input, field, item.value)); setResults(null);}}>{String(item.value)} ({item.count})</Button>)}
        </details>)}</div>
        {!results.items.length ? <Empty>No accessible issues match this query. Try fewer filters or a shorter token prefix.</Empty> : <ol className="search-results">{results.items.map(issue => <li key={issue.id} data-testid={'search-result-' + issue.id}>
          <article><h3><a href={routeLink('/issues/' + issue.id)}>{issue.key} · <Highlight segments={issue.highlights.title}/></a></h3>
            <p><Highlight segments={issue.highlights.description}/></p>
            {issue.matchFields.includes('comments') && <p className="search-comment">Discussion: <Highlight segments={issue.highlights.comments}/></p>}
            <p>{issue.statusName} · priority {issue.priority} · {issue.assignee?.name ?? 'Unassigned'} · updated {new Date(issue.updatedAt).toLocaleString()}</p>
            <p>{issue.labels.map(label => <span className="label" key={label.id}>{label.name}</span>)}</p>
          </article>
        </li>)}</ol>}
        <div className="actions"><Button disabled={busy || history.length < 2} onClick={event => run(event, previousSearchPage(history))}>Previous</Button>
          <span>Page {history.length}</span><Button disabled={busy || !results.nextCursor} onClick={event => run(event, nextSearchPage(history, results.nextCursor))}>Next</Button></div>
        <a href={'#' + searchLocation(orgId, input, projectId)}>Link to this query</a>
      </section>}
    </>}
  </Page>;
}

.search-controls { display: flex; flex-wrap: wrap; align-items: end; gap: 1rem; }
.search-controls .field { min-width: 15rem; flex: 1; }
