.search-results article, .saved-filters article { padding: 1rem 0; border-bottom: 1px solid #cbd5e1; }
.search-results h3 { margin: 0 0 .5rem; }
.search-results mark { background: #fef08a; color: #111827; border-radius: .15rem; }
.search-results p { white-space: pre-wrap; overflow-wrap: anywhere; }
